.ac-compass-cal__btn--manual {
  background: linear-gradient(90deg, #7ec8ff, #5c9dff);
  color: #04203f;
}

.ac-compass-cal__btn--mouse {
  background: linear-gradient(90deg, #c4b5fd, #818cf8);
  color: #1e1b4b;
}

/* Bandeau compact sous la boussole */
.ac-compass-cal-strip {
  width: 100%;
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 0.55rem 0.75rem;
  border-radius: 0.6rem;
  padding: 0.55rem 0.7rem;
  font-size: 0.78rem;
  line-height: 1.35;
}

.ac-compass-cal-strip--warn {
  background: rgba(70, 52, 14, 0.5);
  border: 1px solid rgba(255, 196, 60, 0.4);
  color: #ffe2a8;
}

.ac-compass-cal-strip--ok {
  background: rgba(16, 52, 30, 0.5);
  border: 1px solid rgba(93, 216, 121, 0.45);
  color: #c9ffd6;
}

.ac-compass-cal-strip--mouse {
  background: rgba(36, 28, 70, 0.55);
  border: 1px solid rgba(167, 139, 250, 0.5);
  color: #e9e0ff;
}

.ac-compass-cal-strip__msg {
  flex: 1 1 12rem;
  font-weight: 600;
}

.ac-compass-cal-strip__saved {
  font-weight: 500;
  opacity: 0.85;
}

.ac-compass-cal-strip__actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.4rem;
  align-items: center;
}

.ac-compass-cal-strip .ac-compass-cal__btn {
  align-self: auto;
  white-space: nowrap;
}

.ac-compass-cal-strip .ac-compass-cal__btn--ghost {
  padding: 0.4rem 0.75rem;
}

/* Modale de recalage */
.ac-cal-backdrop {
  position: fixed;
  inset: 0;
  z-index: 1100;
  background: rgba(4, 10, 24, 0.62);
  backdrop-filter: blur(3px);
}

.ac-cal-modal {
  position: fixed;
  z-index: 1101;
  left: 50%;
  top: 50%;
  transform: translate(-50%, -50%);
  width: min(26rem, calc(100vw - 1.25rem));
  max-height: min(92vh, 40rem);
  display: flex;
  flex-direction: column;
  background: linear-gradient(165deg, #121a2e 0%, #0b1220 100%);
  border: 1px solid rgba(120, 170, 255, 0.35);
  border-radius: 0.75rem;
  box-shadow: 0 18px 48px rgba(0, 0, 0, 0.45);
  overflow: hidden;
  color: #e8eefc;
}

.ac-cal-modal__header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
  padding: 0.75rem 0.9rem;
  border-bottom: 1px solid rgba(120, 170, 255, 0.2);
  background: linear-gradient(90deg, rgba(30, 58, 120, 0.55), rgba(20, 35, 70, 0.4));
}

.ac-cal-modal__title {
  margin: 0;
  font-size: 1rem;
  font-weight: 700;
}

.ac-cal-modal__close {
  border: 0;
  background: transparent;
  color: #cfe0ff;
  font-size: 1.1rem;
  line-height: 1;
  padding: 0.2rem 0.35rem;
  cursor: pointer;
  opacity: 0.9;
}

.ac-cal-modal__close:hover {
  opacity: 1;
}

.ac-cal-modal__body {
  flex: 1 1 auto;
  overflow: auto;
  padding: 0.85rem 0.9rem 1rem;
}

.ac-cal-modal__body .ac-compass-cal {
  background: transparent;
  border: none;
  padding: 0;
}
